    /// # Errors
    ///
    /// Returns `CatalogError::Validation` if `relationshipType` is not in the
    /// vocabulary, `CatalogError::IllegalRelationship` if the triple is not in the
    /// legality table, `CatalogError::NotFound` if either table doesn't exist, or
    /// `CatalogError::Conflict` if storage rejects it (e.g. a duplicate
    /// relationship).
    pub async fn create_relationship(
        &self,
        principal: &Principal,
        from_table_id: Uuid,
        request: CreateRelationship,
    ) -> Result<Relationship, CatalogError> {
        let _ = principal;
        // Vocabulary and legality are checked *before* existence, deliberately:
        // an illegal triple between two nonexistent tables is a triple problem,
        // and reporting 404 would send the client hunting for the wrong bug.
        let relationship_type =
            RelationshipType::parse(&request.relationship_type).map_err(|unknown| {
                CatalogError::Validation(vec![FieldError::new(
                    "relationshipType",
                    FieldErrorCode::Type,
                    format!(
                        "`{}` is not a relationship type; expected one of: {}",
                        unknown.got,
                        RelationshipType::ALL
                            .iter()
                            .map(|r| r.as_str())
                            .collect::<Vec<_>>()
                            .join(", ")
                    ),
                )])
            })?;

        let (from, to) = (EntityKind::Table, EntityKind::Table);
        if !is_legal(from, relationship_type, to) {
            return Err(CatalogError::IllegalRelationship {
                from,
                relationship: relationship_type,
                to,
            });
        }

        if self.storage.get_table(from_table_id).await?.is_none() {
            return Err(CatalogError::NotFound);
        }
        if self.storage.get_table(request.to_table_id).await?.is_none() {
            return Err(CatalogError::NotFound);
        }

        let relationship = Relationship {
            id: Uuid::new_v4(),
            from_entity_type: from.as_str().to_string(),
            from_entity_id: from_table_id,
            relationship_type: relationship_type.as_str().to_string(),
            to_entity_type: to.as_str().to_string(),
            to_entity_id: request.to_table_id,
            created_at: Utc::now(),
        };

        let created = self.storage.create_relationship(relationship).await?;
        self.project_relationship(&created, true).await;
        Ok(created)
    }

    /// # Errors
    ///
    /// Returns an error if the underlying storage fails. Returns `Ok(None)` if the table
    /// itself doesn't exist.
    pub async fn list_relationships_for_table(
        &self,
        table_id: Uuid,
    ) -> Result<Option<Vec<Relationship>>, CatalogError> {
        if self.storage.get_table(table_id).await?.is_none() {
            return Ok(None);
        }

        let relationships = self
            .storage
            .list_relationships_for_entity("table", table_id)
            .await?;
        Ok(Some(relationships))
    }

    /// # Errors
    ///
    /// Returns an error if the underlying storage fails.
    pub async fn delete_relationship(
        &self,
        principal: &Principal,
        id: Uuid,
    ) -> Result<bool, CatalogError> {
        let _ = principal;
        // Read before deleting: a retraction has to name the exact facts it
        // withdraws, and after the row is gone there is nothing left to name
        // them from.
        let existing = self.storage.get_relationship(id).await.unwrap_or(None);
        let deleted = self.storage.delete_relationship(id).await?;
        if let (true, Some(relationship)) = (deleted, existing) {
            self.project_relationship(&relationship, false).await;
        }
        Ok(deleted)
    }

    // ---- asset hierarchy (Epic 2) ----

    /// Creates or converges an asset, deriving its FQN from the parent chain.
    ///
    /// Converging means calling this twice with the same `parent_id`/`name`
    /// updates the existing asset rather than creating a duplicate — a
    /// connector re-running its ingest gets the same entity back each time.
    ///
    /// # Errors
    ///
    /// `Validation` if the FQN cannot be derived or the parent is the wrong
    /// kind; `NotFound` if the parent does not exist.
    ///
    /// ```
    /// use std::sync::Arc;
    /// use graph_owl_api::{Catalog, UpsertAsset};
    /// use graph_owl_core::{AssetKind, Principal};
    /// use graph_owl_storage_memory::InMemoryStorage;
    ///
    /// # tokio::runtime::Runtime::new().unwrap().block_on(async {
    /// let catalog = Catalog::new(Arc::new(InMemoryStorage::default()));
    /// let system = Principal::system();
    ///
    /// let created = catalog
    ///     .upsert_asset(&system, UpsertAsset {
    ///         kind: AssetKind::Service,
    ///         name: "orders-api".to_string(),
    ///         parent_id: None,
    ///         description: Some("Order placement".to_string()),
    ///         properties: None,
    ///         extension: None,
    ///     })
    ///     .await
    ///     .expect("a root-kind asset needs no parent");
    /// assert_eq!(created.fully_qualified_name, "orders-api");
    /// # });
    /// ```
    #[tracing::instrument(name = "catalog.upsert_asset", skip_all)]
    pub async fn upsert_asset(
        &self,
        principal: &Principal,
        request: UpsertAsset,
    ) -> Result<Asset, CatalogError> {
        let _ = principal;

        // **Before anything is written.** An `extension` value that reached
        // storage unvalidated would be the description field again with extra
        // steps, and removing it later is a migration rather than a fix.
        self.check_extension(request.kind, request.extension.as_ref())
            .await?;

        // Same reasoning, for the closed-enum fields Epic 34 adds inside
        // `properties` itself (never validated before this epic, because
        // Table/Column carry nothing closed there).
        check_family_properties(request.kind, request.properties.as_ref())?;

        // Containment is checked against the *actual* parent, not a claim in
        // the request: a column under a schema is a hierarchy corruption every
        // later traversal has to cope with.
        let parent = match request.parent_id {
            Some(parent_id) => {
                let parent = self
                    .storage
                    .get_asset(parent_id)
                    .await?
                    .ok_or(CatalogError::NotFound)?;
                // Epic 34 Slice E: a container may also nest inside another
                // container — `AssetKind::parent_kind` cannot express "one of
                // several kinds" (it is a single terminating chain, which
                // `depth()` walks to termination), so the second valid parent
                // is special-cased here rather than in the kind's own
                // declared parent. See `AssetKind::Container`'s own doc
                // comment for the resulting, recorded gap.
                let is_nested_container =
                    request.kind == AssetKind::Container && parent.kind == AssetKind::Container;
                // Epic 34 Slice E, second half: "`data_model` holds columns
                // where the format is structured (Parquet, Avro), reusing
                // the column machinery" — the identical single-parent
                // limitation as the nesting case above, so it gets the same
                // treatment: a `Column` under a `Container` is a second
                // special-cased parent, not a new kind. Recorded as decision
                // 28 in `00b-architecture.md`.
                let is_column_under_container =
                    request.kind == AssetKind::Column && parent.kind == AssetKind::Container;
                if request.kind.parent_kind() != Some(parent.kind)
                    && !is_nested_container
                    && !is_column_under_container
                {
                    return Err(CatalogError::Validation(vec![FieldError::new(
                        "parentId",
                        FieldErrorCode::Type,
                        format!(
                            "a `{}` is contained by a `{}`, not a `{}`",
                            request.kind,
                            request
                                .kind
                                .parent_kind()
                                .map_or_else(|| "nothing".to_string(), |k| k.to_string()),
                            parent.kind
                        ),
                    )]));
                }
                Some(parent)
            }
            None => {
                if request.kind.parent_kind().is_some() {
                    return Err(CatalogError::Validation(vec![FieldError::new(
                        "parentId",
                        FieldErrorCode::Required,
                        format!("a `{}` requires a parent", request.kind),
                    )]));
                }
                None
            }
        };

        // Epic 34 Slice C: a task DAG cycle is rejected before the write,
        // the same way the plan reuses Epic 11's own cycle detector for
        // glossary terms — a poly-hierarchy walk over an edge list, here
        // built from every sibling task's own `downstreamTasks` rather than
        // a `broader` relation.
        if request.kind == AssetKind::Task
            && let Some(pipeline) = &parent
        {
            self.check_no_task_cycle(pipeline.id, &request.name, request.properties.as_ref())
                .await?;
        }

        // Epic 34 Slice D: a feature's `featureSources` names table columns
        // by FQN — checked before the write, the same reasoning as the task
        // cycle check above, so a nonexistent source is a `400` rather than
        // a lineage edge silently never derived.
        if request.kind == AssetKind::Feature {
            self.check_feature_sources(request.properties.as_ref())
                .await?;
        }

        let fully_qualified_name = match &parent {
            Some(parent) => fqn::child_of(&parent.fully_qualified_name, &request.name),
            None => fqn::derive(&[&request.name]),
        }
        .map_err(|error| {
            CatalogError::Validation(vec![FieldError::new(
                "name",
                FieldErrorCode::Type,
                error.to_string(),
            )])
        })?;

        let now = Utc::now();
        // Read before the write so the projection can diff against it. A
        // create has no prior state and projects its whole self; an upsert
        // over an existing FQN is an update and must retract what it replaces.
        let before = self
            .storage
            .get_asset_by_fqn(&fully_qualified_name)
            .await
            .unwrap_or(None);

        let written = self
            .storage
            .upsert_asset(Asset {
                id: Uuid::new_v4(),
                kind: request.kind,
                name: request.name,
                fully_qualified_name,
                parent_id: request.parent_id,
                description: request.description,
                properties: request.properties,
                extension: request.extension.clone(),
                owners: Vec::new(),
                version: EntityVersion::initial(),
                updated_by: principal.id.clone(),
                // No diff on the initial version: there was nothing before it,
                // and an empty diff would read as "nothing changed" rather than
                // "this is where it began".
                change_description: None,
                deleted: false,
                deleted_at: None,
                created_at: now,
                updated_at: now,
                lifecycle: Default::default(),
                deprecation: None,
            })
            .await?;

        self.project(before.clone(), &written).await;
        // Past every early return above, so the write has committed.
        //
        // `upsert_asset` is create-or-update behind one method, and the caller
        // never says which it meant — a connector supplies a fresh Uuid on
        // every run and lets the FQN decide. Prior state is therefore the only
        // honest signal: no `before` is a creation, a `before` is an update.
        self.announce(match &before {
            None => Some(ChangeEvent::created(
                event_subject(&written),
                written.version,
                &principal.id,
            )),
            // Storage does not version or diff an upsert — a connector re-run
            // is a mechanical sync, not a curated edit (`03-versioning.md`).
            // The facade holds both states, so it computes the diff here, and
            // `ChangeEvent::updated` drops the event when nothing moved.
            Some(before) => ChangeEvent::updated(
                event_subject(&written),
                before.version,
                written.version,
                ChangeDescription::between(&syncable_fields(before), &syncable_fields(&written)),
                &principal.id,
            ),
        });

        // Epic 34 Slice A: "search ranks a dashboard by its own name and by
        // its charts' names" — but `search_vector` is a per-row generated
        // column (Epic 8 Slice A), computed from that row's own name/FQN/
        // description alone; it has no way to reach into a child row. The
        // only way to satisfy the criterion without changing how
        // `search_vector` is computed for every kind is to denormalize the
        // chart names onto the dashboard's own row, in the weight-D slot the
        // migration's own comment reserved for exactly this kind of later
        // need. Recorded in `plans/00b-architecture.md`'s decision log per
        // the epic's own instruction.
        if written.kind == AssetKind::Chart
            && let Some(dashboard_id) = written.parent_id
        {
            self.sync_dashboard_chart_names(dashboard_id).await?;
        }

        // Phase 3 item 3.7 (Decision 5's "column names" tier). The identical
        // gap Epic 34 Slice A already solved for a dashboard's charts, for a
        // table's columns instead: `properties.columnNames` shares the same
        // weight-D slot `sync_dashboard_chart_names` already writes
        // `chartNames` into (`V56__search_vector_column_names.sql`).
        if written.kind == AssetKind::Column
            && let Some(table_id) = written.parent_id
        {
            self.sync_table_column_names(table_id).await?;
        }

        // Epic 34 Slice D: "lineage edges are derived from feature sources
        // rather than asserted separately" — a caller names the columns a
        // feature was built from and the table-to-model edge follows
        // automatically, the same "after the write, before it's returned"
        // shape as the chart-name sync above.
        if written.kind == AssetKind::Feature
            && let Some(model_id) = written.parent_id
        {
            self.derive_lineage_from_feature_sources(principal, model_id, &written)
                .await?;
        }

        Ok(written)
    }

    /// Recomputes and persists a dashboard's `properties.chartNames` from its
    /// current chart children — see the "search ranks a dashboard" note in
    /// [`Self::upsert_asset`]. A system-maintained cache field, not a user
    /// edit: written directly through storage rather than through
    /// `Catalog::upsert_asset` itself, so refreshing it neither bumps the
    /// dashboard's own semantic version nor emits a change event a reader
    /// would have no context for ("what changed?" — nothing a person did).
    async fn sync_dashboard_chart_names(&self, dashboard_id: Uuid) -> Result<(), CatalogError> {
        let Some(mut dashboard) = self.storage.get_asset(dashboard_id).await? else {
            // The dashboard itself may already be gone (e.g. a cascading
            // delete removed it and this chart with it) — nothing to sync.
            return Ok(());
        };
        let children = self.storage.list_children(Some(dashboard_id)).await?;
        let chart_names: Vec<&str> = children
            .iter()
            .filter(|child| child.kind == AssetKind::Chart && !child.deleted)
            .map(|child| child.name.as_str())
            .collect();

        let mut properties = dashboard
            .properties
            .and_then(|p| p.as_object().cloned())
            .unwrap_or_default();
        if chart_names.is_empty() {
            properties.remove("chartNames");
        } else {
            properties.insert(
                "chartNames".to_string(),
                serde_json::Value::String(chart_names.join(" ")),
            );
        }
        dashboard.properties = Some(serde_json::Value::Object(properties));
        self.storage.upsert_asset(dashboard).await?;
        Ok(())
    }

    /// Recomputes and persists a table's `properties.columnNames` from its
    /// current column children — [`Self::sync_dashboard_chart_names`]'s own
    /// pattern, for the container/child pair Decision 5's "column names" tier
    /// actually names. Same reasoning throughout: written directly through
    /// storage so refreshing the cache neither bumps the table's semantic
    /// version nor emits a change event nobody's edit produced.
    async fn sync_table_column_names(&self, table_id: Uuid) -> Result<(), CatalogError> {
        let Some(mut table) = self.storage.get_asset(table_id).await? else {
            return Ok(());
        };
        let children = self.storage.list_children(Some(table_id)).await?;
        let column_names: Vec<&str> = children
            .iter()
            .filter(|child| child.kind == AssetKind::Column && !child.deleted)
            .map(|child| child.name.as_str())
            .collect();

        let mut properties = table
            .properties
            .and_then(|p| p.as_object().cloned())
            .unwrap_or_default();
        if column_names.is_empty() {
            properties.remove("columnNames");
        } else {
            properties.insert(
                "columnNames".to_string(),
                serde_json::Value::String(column_names.join(" ")),
            );
        }
        table.properties = Some(serde_json::Value::Object(properties));
        self.storage.upsert_asset(table).await?;
        Ok(())
    }

    /// Asserts a `Table -> MlModel` lineage edge for every distinct table
    /// behind `feature`'s `properties.featureSources` — see the Slice D note
    /// above its call site in [`Self::upsert_asset`]. Each source column's
    /// own parent *is* its table (`Column`'s declared parent kind), so no
    /// further walk up the hierarchy is needed. `check_feature_sources` has
    /// already confirmed every entry resolves, so a lookup failure here
    /// (a source deleted between the check and this call) is skipped rather
    /// than re-reported.
    async fn derive_lineage_from_feature_sources(
        &self,
        principal: &Principal,
        model_id: Uuid,
        feature: &Asset,
    ) -> Result<(), CatalogError> {
        let Some(sources) = feature
            .properties
            .as_ref()
            .and_then(|p| p.get("featureSources"))
            .and_then(|v| v.as_array())
        else {
            return Ok(());
        };

        let mut table_ids: Vec<Uuid> = Vec::new();
        for source in sources {
            let Some(fqn) = source.as_str() else {
                continue;
            };
            let Some(column) = self.storage.get_asset_by_fqn(fqn).await? else {
                continue;
            };
            if let Some(table_id) = column.parent_id
                && !table_ids.contains(&table_id)
            {
                table_ids.push(table_id);
            }
        }

        for table_id in table_ids {
            match self
                .assert_lineage(
                    principal,
                    table_id,
                    model_id,
                    graph_owl_core::relationship_type::RelationshipType::Feeds,
                    graph_owl_core::lineage::LineageDetails {
                        source: graph_owl_core::lineage::LineageSource::Connector,
                        query: None,
                        description: None,
                        pipeline: None,
                        openlineage_event_id: None,
                    },
                )
                .await
            {
                // Re-saving a feature against the same sources re-derives
                // the same edge; already-asserted is success here, not a
                // failure to surface — the edge the caller wanted exists
                // either way.
                Ok(_) | Err(CatalogError::Conflict { .. }) => {}
                Err(error) => return Err(error),
            }
        }
        Ok(())
    }

    /// # Errors
    /// Returns an error if the underlying storage fails.
    #[tracing::instrument(name = "catalog.get_asset", skip_all)]
    pub async fn get_asset(&self, id: Uuid) -> Result<Option<Asset>, CatalogError> {
        Ok(self.storage.get_asset(id).await?)
    }

    /// # Errors
    /// Returns an error if the underlying storage fails.
    pub async fn get_asset_by_fqn(&self, fqn: &str) -> Result<Option<Asset>, CatalogError> {
        Ok(self.storage.get_asset_by_fqn(fqn).await?)
    }

    /// Cheapest possible round trip to storage, for readiness.
    ///
    /// # Errors
    ///
    /// Returns an error if storage is unreachable.
    pub async fn ping(&self) -> Result<(), CatalogError> {
        self.storage.ping().await.map_err(Into::into)
    }

    /// Resolves a principal's policies once per request.
    ///
    /// # Errors
    ///
    /// Returns an error if the underlying storage fails.
    pub async fn policies_for(&self, principal: &Principal) -> Result<Vec<Policy>, CatalogError> {
        if principal.is_admin {
            return Ok(Vec::new());
        }
        Ok(self.storage.policies_for_roles(&principal.roles).await?)
    }

    /// The predicate for one principal and operation, cached.
    ///
    /// The cache sits **here** rather than around `policies_for`, because the
    /// compiled predicate is what every read path actually consumes and
    /// compiling it is the other half of the cost. Caching the policies alone
    /// would keep the round trip and pay the compile on every request.
    #[tracing::instrument(name = "catalog.predicate_for", skip_all)]
    async fn predicate_for(
        &self,
        principal: &Principal,
        operation: MetadataOperation,
    ) -> Result<AccessPredicate, CatalogError> {
        let subject = subject_of(principal);
        let key = DecisionKey::new(&subject, operation);
        if let Some(cached) = self.decisions.get(&key) {
            return Ok(cached);
        }

        let policies = self.policies_for(principal).await?;
        let predicate = compile(&subject, operation, &policies);
        self.decisions.insert(key, predicate.clone());
        Ok(predicate)
    }

    /// The named-graph counterpart of [`Self::predicate_for`] — Epic 105's
    /// own follow-up, named but not built when domain neutrality shipped:
    /// "access to `graph:import:{source}` is a policy decision rather than
    /// a namespace one" (`plans/105-domain-neutrality.md`,
    /// `plans/105y-named-graph-policy.md`).
    ///
    /// **Not cached**, unlike [`Self::predicate_for`]: `self.decisions`
    /// keys on `(subject, operation)` alone, which would collide with the
    /// FQN predicate for the identical request — reusing it here would mean
    /// whichever compilation ran first for a given principal silently
    /// answers both. A second cache keyed on the resource dimension too is
    /// the correct fix once this path is warm enough to need one; until
    /// then, compiling on every call is the same cost `predicate_for` paid
    /// before its own cache existed, not a new one.
    async fn named_graph_predicate_for(
        &self,
        principal: &Principal,
        operation: MetadataOperation,
    ) -> Result<AccessPredicate, CatalogError> {
        let subject = subject_of(principal);
        let policies = self.policies_for(principal).await?;
        Ok(graph_owl_authz::compile_named_graph(
            &subject, operation, &policies,
        ))
    }

    /// Connection-pool occupancy, for the operational gauge.
    #[must_use]
    pub fn pool_stats(&self) -> Option<graph_owl_storage::PoolStats> {
        self.storage.pool_stats()
    }

    /// Save a connector configuration.
    ///
    /// `secret` is `None` to leave an existing credential alone: an
    /// edit-then-save round trip cannot resend what it was never given.
    ///
    /// # Errors
    ///
    /// `Validation` if the connector or service name is blank.
    /// `Storage` if the write fails.
    #[tracing::instrument(name = "catalog.save_connector_config", skip_all)]
    pub async fn save_connector_config(
        &self,
        connector: &str,
        service_name: &str,
        settings: serde_json::Value,
        secret: Option<&str>,
    ) -> Result<graph_owl_storage::ConnectorConfig, CatalogError> {
        let mut problems = Vec::new();
        if connector.trim().is_empty() {
            problems.push(FieldError::new(
                "connector",
                FieldErrorCode::Required,
                "which connector this configures".to_string(),
            ));
        }
        if service_name.trim().is_empty() {
            problems.push(FieldError::new(
                "serviceName",
                FieldErrorCode::Required,
                "the service this configuration is for".to_string(),
            ));
        }
        // A blank secret is not a secret. Accepting `""` would set `has_secret`
        // and then fail at connection time with a credential error nobody can
        // explain.
        if secret.is_some_and(|s| s.trim().is_empty()) {
            problems.push(FieldError::new(
                "secret",
                FieldErrorCode::Type,
                "a blank secret is not a credential; omit the field to keep the \
                 existing one"
                    .to_string(),
            ));
        }
        if !problems.is_empty() {
            return Err(CatalogError::Validation(problems));
        }

        let config = graph_owl_storage::ConnectorConfig {
            id: Uuid::new_v4(),
            connector: connector.to_string(),
            service_name: service_name.to_string(),
            settings,
            // Set from what storage actually holds, on the read below — a value
            // computed here would claim a credential this call may not have
            // supplied.
            has_secret: false,
        };
        self.storage
            .upsert_connector_config(&config, secret)
            .await?;

        self.storage
            .connector_configs()
            .await?
            .into_iter()
            .find(|c| c.connector == connector && c.service_name == service_name)
            .ok_or_else(|| {
                CatalogError::Storage(StorageError::Unexpected(
                    "the configuration vanished between write and read".to_string(),
                ))
            })
    }

