    // ---- Epic 24 Slice F: metric lineage reconciliation ----

    /// Replace what a metric declares as its sources.
    ///
    /// Runs the declared list through
    /// [`graph_owl_core::metric::reconcile_lineage`] before storing —
    /// deduplicated, and a metric naming itself excluded, the same rule the
    /// core function applies everywhere it is used. **Scoped to
    /// `metric_sources`**, not `lineage_edges` (see
    /// [`graph_owl_storage::Storage::update_metric_sources`]'s doc): a
    /// metric is not an asset, so this is not yet reachable by Epic 29
    /// traversal.
    ///
    /// # Errors
    ///
    /// `NotFound` if the metric does not exist. `Validation` if a named
    /// source is not a known asset.
    #[tracing::instrument(name = "catalog.set_metric_sources", skip_all)]
    pub async fn set_metric_sources(
        &self,
        metric_id: Uuid,
        sources: Vec<String>,
    ) -> Result<graph_owl_storage::MetricRecord, CatalogError> {
        if self.storage.get_metric(metric_id).await?.is_none() {
            return Err(CatalogError::NotFound);
        }
        for source in &sources {
            if self.storage.get_asset_by_fqn(source).await?.is_none() {
                return Err(CatalogError::Validation(vec![FieldError::new(
                    "sourceAssets",
                    FieldErrorCode::Type,
                    format!("`{source}` is not a known asset"),
                )]));
            }
        }

        let metric_id_str = metric_id.to_string();
        let plan = graph_owl_core::metric::reconcile_lineage(&metric_id_str, &sources, &[]);
        let mut resolved: Vec<String> = plan.to_add.into_iter().map(|edge| edge.from).collect();
        resolved.sort();

        self.storage
            .update_metric_sources(metric_id, &resolved)
            .await?
            .ok_or(CatalogError::NotFound)
    }

    /// Change what roles a user holds.
    ///
    /// **Invalidates the decision cache, and that is the entire point.** A
    /// compiled predicate is cached per subject and operation, and a revoked
    /// role that keeps working until some TTL elapses is a revocation whose
    /// window is invisible to whoever performed it. There is deliberately no
    /// TTL (see [`Self::invalidate_authorization`]), so this call is the only
    /// thing that expires an entry — omitting it would leave the old access in
    /// force with nothing to show why.
    ///
    /// The whole cache rather than one subject's entries: roles are compiled
    /// against policies that name *other* subjects too, so a change to one
    /// person can alter what a group-based rule grants everybody. Clearing
    /// selectively would be right most of the time, which is the worst
    /// property a security control can have.
    ///
    /// # Errors
    ///
    /// `NotFound` if there is no such user — creating one as a side effect of
    /// granting it roles would let a typo mint a principal.
    /// `Storage` if the write fails.
    #[tracing::instrument(name = "catalog.set_user_roles", skip_all)]
    /// Create or update a user's record — Epic 11 Slice A's missing half.
    ///
    /// **Roles are deliberately not settable here.** `set_user_roles` is the one
    /// path that grants them, and it invalidates the authorization cache; a second
    /// path that also wrote roles would have to remember to do the same, and the
    /// one that forgot would leave stale permissions in force. Creating a user
    /// grants nothing, which is also the right default for onboarding.
    ///
    /// # Errors
    ///
    /// `Validation` if the id or display name is blank — an unnamed principal is
    /// one nobody can pick from a list.
    pub async fn upsert_user_record(
        &self,
        id: &str,
        display_name: &str,
        email: Option<&str>,
    ) -> Result<StoredUser, CatalogError> {
        let mut problems = Vec::new();
        if id.trim().is_empty() {
            problems.push(FieldError::new(
                "id",
                FieldErrorCode::Required,
                "a user needs an id — the identity provider's subject".to_string(),
            ));
        }
        if display_name.trim().is_empty() {
            problems.push(FieldError::new(
                "displayName",
                FieldErrorCode::Required,
                "a user needs a name somebody can recognise in an owner list".to_string(),
            ));
        }
        if !problems.is_empty() {
            return Err(CatalogError::Validation(problems));
        }

        // Existing roles and flags are preserved: this endpoint renames and
        // records, it does not re-provision. Overwriting `is_admin` from a body
        // would make a rename a privilege change.
        let existing = self.storage.find_user(id).await?;
        let user = StoredUser {
            id: id.to_string(),
            display_name: display_name.to_string(),
            email: email.map(ToString::to_string),
            is_admin: existing.as_ref().is_some_and(|u| u.is_admin),
            is_bot: existing.as_ref().is_some_and(|u| u.is_bot),
            roles: existing.map(|u| u.roles).unwrap_or_default(),
        };
        self.storage.upsert_user(&user).await?;
        Ok(user)
    }

    /// Replaces a user's role set.
    ///
    /// # Errors
    ///
    /// [`CatalogError::Storage`] if the write fails.
    pub async fn set_user_roles(
        &self,
        id: &str,
        roles: Vec<String>,
    ) -> Result<StoredUser, CatalogError> {
        let existing = self
            .storage
            .find_user(id)
            .await?
            .ok_or(CatalogError::NotFound)?;

        let updated = StoredUser { roles, ..existing };
        self.storage.upsert_user(&updated).await?;
        // After the write, never before: invalidating first leaves a window in
        // which a concurrent request re-populates the cache from the old rows.
        self.invalidate_authorization();
        Ok(updated)
    }

    /// Forget every cached authorization decision.
    ///
    /// Called by anything that changes what a decision was computed *from* — a
    /// role assignment, a policy edit. **Invalidation is the only thing that
    /// expires an entry**: there is no TTL, deliberately, because a TTL makes
    /// staleness the normal case and the window in which a revoked role still
    /// works is invisible to whoever revoked it.
    pub fn invalidate_authorization(&self) {
        self.decisions.invalidate();
    }

    /// # Errors
    ///
    /// Returns an error if the underlying storage fails.
    #[tracing::instrument(name = "catalog.list_assets_for", skip_all)]
    pub async fn list_assets_for(
        &self,
        principal: &Principal,
        filter: &graph_owl_storage::AssetFilter<'_>,
        page: &PageRequest,
    ) -> Result<Page<Asset>, CatalogError> {
        let predicate = self
            .predicate_for(principal, MetadataOperation::ViewBasic)
            .await?;
        Ok(self
            .storage
            .list_assets_visible(filter, page, &predicate)
            .await?)
    }

    /// # Errors
    ///
    /// Returns an error if the underlying storage fails.
    #[tracing::instrument(name = "catalog.search_assets_for", skip_all)]
    pub async fn search_assets_for(
        &self,
        principal: &Principal,
        query: &str,
        filter: &graph_owl_storage::AssetFilter<'_>,
        page: &PageRequest,
    ) -> Result<Page<graph_owl_storage::SearchHit>, CatalogError> {
        let predicate = self
            .predicate_for(principal, MetadataOperation::ViewBasic)
            .await?;
        Ok(self
            .storage
            .search_assets_visible(query, filter, page, &predicate)
            .await?)
    }

    /// Rank catalog assets by how closely their name matches a free-text
    /// candidate — Epic 105 P10's `resolve_entity()` tool, the platform
    /// doc's entity-linking primitive. An agent that has a name or id
    /// from unstructured text and needs to know which real catalog asset
    /// it refers to gets back real assets with a normalized similarity
    /// score, which is the question full-text relevance ranking does not
    /// answer — `search_assets`'s own ranking says "what mentions this
    /// text", not "how alike is this asset's name to that text".
    ///
    /// **Reuses [`search_assets_for`] for candidate retrieval** — the
    /// identical policy-filtered, bounded search the `search_assets` MCP
    /// tool already serves — rather than a second search index, then
    /// re-scores each hit with
    /// [`graph_owl_resolution::rule_match::similarity`].
    ///
    /// **Trigram n-grams (`n = 3`), not a chosen-for-this-tool number.**
    /// Three is the standard n-gram size for short-identifier fuzzy
    /// matching — the same default Postgres's own `pg_trgm` extension
    /// uses, on the same storage engine this project runs on — and the
    /// padding `graph_owl_resolution::rule_match::ngrams` already applies
    /// keeps it from degrading on short values (its own doc comment:
    /// unpadded, a 3-character value has exactly one trigram, comparing
    /// as all-or-nothing).
    ///
    /// **Scoped to catalog assets, for the identical reason `traverse`/
    /// `analytics` are**: a pack-domain subject has no policy model yet.
    ///
    /// # Errors
    ///
    /// `Validation` if `limit` is zero or exceeds the page size cap —
    /// [`PageRequestError`] mapped the same way `graph-owl-server`'s own
    /// `AppError` conversion does, since a caller here deserves the same
    /// field-named diagnosis an HTTP caller gets. `Storage` if the search
    /// fails.
    ///
    /// # Panics
    ///
    /// Never in practice: the `n = 3` above is a fixed literal, which is
    /// the one input [`RuleMatchError::InvalidNGramSize`] can ever fire
    /// on, and every produced score is a finite `0.0..=1.0` ratio, which
    /// can never fail `partial_cmp` the way `NaN` would.
    ///
    /// [`PageRequestError`]: graph_owl_core::page::PageRequestError
    /// [`RuleMatchError::InvalidNGramSize`]: graph_owl_resolution::rule_match::RuleMatchError::InvalidNGramSize
    pub async fn resolve_entity(
        &self,
        principal: &Principal,
        query: &str,
        limit: usize,
    ) -> Result<Vec<ResolvedEntity>, CatalogError> {
        let field_error = |error: graph_owl_core::page::PageRequestError| match error {
            graph_owl_core::page::PageRequestError::LimitTooLarge { requested, max } => {
                FieldError::new(
                    "limit",
                    FieldErrorCode::Value,
                    format!("`limit` must be at most {max}, got {requested}"),
                )
            }
            graph_owl_core::page::PageRequestError::LimitZero => FieldError::new(
                "limit",
                FieldErrorCode::Value,
                "`limit` must be at least 1".to_string(),
            ),
            graph_owl_core::page::PageRequestError::MalformedCursor => {
                unreachable!("this method never passes a cursor")
            }
        };
        let page = self
            .search_assets_for(
                principal,
                query,
                &graph_owl_storage::AssetFilter::default(),
                &PageRequest::new(Some(limit), None)
                    .map_err(|e| CatalogError::Validation(vec![field_error(e)]))?,
            )
            .await?;

        let mut scored: Vec<ResolvedEntity> = page
            .data
            .into_iter()
            .map(|hit| {
                let score = graph_owl_resolution::rule_match::similarity(
                    query,
                    &hit.asset.fully_qualified_name,
                    &graph_owl_resolution::rule_match::SimilarityStrategy::NGram { n: 3 },
                )
                .expect("n = 3 is always a valid n-gram size");
                ResolvedEntity {
                    asset: hit.asset,
                    score,
                }
            })
            .collect();
        scored.sort_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .expect("a similarity score is never NaN")
        });
        Ok(scored)
    }

    /// Resolve free text to a candidate graph subject, scored by how
    /// closely it matches one of that subject's own literal properties —
    /// Epic 105 P9's entity linking (`plans/105w-entity-linking.md`). See
    /// [`LinkedEntity`]'s own doc comment for how this differs from
    /// [`Self::resolve_entity`].
    ///
    /// Reuses [`Self::sparql`] rather than a new storage-layer scan:
    /// authorization scoping and the query budget both already live there,
    /// and a full literal scan is exactly what `scoped_facts`' own
    /// `max_facts` truncation already exists to bound. The scan itself has
    /// no predicate to push down — every literal property is a candidate,
    /// by design, since a pack's own naming is never known here.
    ///
    /// # Errors
    ///
    /// `Storage` if no graph engine is configured or the scan fails.
    ///
    /// # Panics
    ///
    /// Never in practice: the `n = 3` above is a fixed literal, the one
    /// input [`RuleMatchError::InvalidNGramSize`] can ever fire on, and
    /// every produced score is a finite `0.0..=1.0` ratio, which can never
    /// fail `partial_cmp` the way `NaN` would — the same reasoning
    /// [`Self::resolve_entity`]'s own `# Panics` section already states.
    ///
    /// [`RuleMatchError::InvalidNGramSize`]: graph_owl_resolution::rule_match::RuleMatchError::InvalidNGramSize
    pub async fn link_entity(
        &self,
        principal: &Principal,
        query: &str,
        limit: usize,
    ) -> Result<Vec<LinkedEntity>, CatalogError> {
        let outcome = self
            .sparql(
                principal,
                "SELECT ?s ?v WHERE { ?s ?p ?v . FILTER(isLiteral(?v)) }",
                None,
                SparqlBudget::default(),
            )
            .await?;

        // Best *lexical* match per subject, not one row per matching
        // literal — a caller wants one seed per candidate entity, the same
        // "one candidate, not one row per matching field" shape
        // `resolve_entity` already has. `(matched_value, lexical)`, not the
        // full `LinkedEntity` yet: the graph term is filled in afterward,
        // once per surviving subject rather than once per literal row.
        let mut best: std::collections::HashMap<Sid, (String, f64)> =
            std::collections::HashMap::new();
        for row in outcome.rows {
            let (Some(subject_term), Some(value_term)) = (row.get("s"), row.get("v")) else {
                continue;
            };
            let Some(subject) = graph_owl_core::flake::Sid::from_iri(bare_term(subject_term))
            else {
                continue;
            };
            let matched_value = bare_term(value_term).to_string();
            let lexical = graph_owl_resolution::rule_match::similarity(
                query,
                &matched_value,
                &graph_owl_resolution::rule_match::SimilarityStrategy::NGram { n: 3 },
            )
            .expect("n = 3 is always a valid n-gram size");

            best.entry(subject)
                // Strictly `>`: on a tie the first-seen literal keeps the
                // slot. Arbitrary, and deliberately so — the fused `score`
                // depends on `lexical`, which is identical either way, so
                // no caller-observable behaviour depends on which literal
                // string wins a tie, only that one wins consistently
                // rather than depending on fetch order.
                .and_modify(|existing| {
                    if lexical > existing.1 {
                        *existing = (matched_value.clone(), lexical);
                    }
                })
                .or_insert((matched_value, lexical));
        }

        // Hybrid-search fusion — Epic 105 P9's other named gap
        // (`plans/105x-hybrid-search.md`): lexical similarity alone cannot
        // distinguish two textually-similar candidates by how connected
        // each actually is in the graph. No embedding exists for a graph
        // subject in general (only memories have one, Epic 31), so
        // `semantic` stays honestly `None` throughout.
        let weights = graph_owl_core::hybrid::HybridWeights::default();
        let mut scored = Vec::with_capacity(best.len());
        for (subject, (matched_value, lexical)) in best {
            let graph = self.link_entity_graph_signal(&subject).await;
            let fused = graph_owl_core::hybrid::fuse(lexical, None, graph, &weights);
            scored.push(LinkedEntity {
                subject,
                matched_value,
                lexical: fused.lexical,
                graph: fused.graph,
                score: fused.total,
            });
        }

        scored.sort_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .expect("a similarity score is never NaN")
        });
        scored.truncate(limit);
        Ok(scored)
    }

    /// How connected `subject` is within one hop, `0.0..=1.0`, `None` when
    /// no traversal engine is configured — the same honesty
    /// [`graph_owl_core::recall::Candidate::semantic`] already established
    /// for a signal that may simply never have been measured.
    ///
    /// The seed itself is excluded from the count (every node trivially
    /// "reaches itself"), and a traversal failure degrades to `None` rather
    /// than failing the whole call — the same posture
    /// [`Self::node_sources`]'s own per-node lookup already takes.
    async fn link_entity_graph_signal(&self, subject: &Sid) -> Option<f64> {
        let traversal = self.traversal.as_ref()?;
        let bounds = Bounds {
            max_hops: 1,
            max_nodes: 200,
        };
        let result = traversal
            .neighbours(subject, Direction::Both, bounds, &EdgeFilter::default())
            .await
            .ok()?;
        let others = result.reached.len().saturating_sub(1);
        Some((others as f64 / f64::from(u32::try_from(bounds.max_nodes - 1).unwrap_or(1))).min(1.0))
    }

    /// Turn `extension.<name>[.gte|.lte]=<text>` pairs into typed filters.
    ///
    /// **An undefined name is a `400`, never an empty page.** A typo'd filter
    /// that silently matched nothing is the failure mode `00d-api-conventions.md`
    /// singles out: the client reads "no results" as an answer about the data
    /// rather than about the request, and acts on it. That is a data-leak-shaped
    /// bug in reverse — a false negative nobody investigates.
    ///
    /// The value is coerced against the **declared type**, which is the reason
    /// this lives in the facade and not in storage: a query string carries only
    /// text, and `retentionDays=30` means the number thirty only because the
    /// definition says so. Coercing by guessing — "does it parse as a number?" —
    /// would make a string property whose values happen to be digits
    /// unfilterable.
    ///
    /// # Errors
    ///
    /// `Validation` naming every filter that does not resolve, not just the
    /// first. `Storage` if the definitions cannot be read.
    pub async fn extension_filters(
        &self,
        kind: Option<AssetKind>,
        requested: &[(String, graph_owl_storage::ExtensionOp, String)],
    ) -> Result<Vec<graph_owl_storage::ExtensionFilter>, CatalogError> {
        if requested.is_empty() {
            return Ok(Vec::new());
        }

        // Every definition, or only the filtered kind's. Unscoped is right when
        // no `kind` was given: `?extension.costCenter=X` with no kind is a
        // question about every entity type that defines it, and scoping it to
        // one arbitrarily would answer a different question silently.
        let definitions = self
            .storage
            .list_custom_properties(kind.map(AssetKind::as_str))
            .await
            .map_err(CatalogError::from)?;

        let mut filters = Vec::with_capacity(requested.len());
        let mut errors = Vec::new();
        for (name, op, raw) in requested {
            let Some((_, definition)) = definitions
                .iter()
                .find(|(_, property)| property.name == *name)
            else {
                errors.push(FieldError::new(
                    format!("extension.{name}"),
                    FieldErrorCode::Value,
                    format!(
                        "`{name}` is not a custom property{}; filtering on it would \
                         silently match nothing",
                        kind.map_or_else(String::new, |k| format!(" of `{k}`"))
                    ),
                ));
                continue;
            };

            match coerce_filter_value(definition.property_type, raw) {
                Some(value) => filters.push(graph_owl_storage::ExtensionFilter {
                    name: name.clone(),
                    op: *op,
                    value,
                }),
                None => errors.push(FieldError::new(
                    format!("extension.{name}"),
                    FieldErrorCode::Type,
                    format!("`{raw}` is not a {}", definition.property_type.as_str()),
                )),
            }
        }

        if errors.is_empty() {
            Ok(filters)
        } else {
            Err(CatalogError::Validation(errors))
        }
    }

